# Post (or update in place) the deterministic CI failure analysis comment.
#
# The comment is rendered from a fixed markdown template using a bounded set
# of failure lines extracted from the failed job logs. No model interprets
# PR-influenced data, so injected instructions in artifacts or logs have no
# sink and no API keys or write-scoped tokens are exposed to an interpreter.
#
# Required environment variables:
#   GH_TOKEN         - token with actions:read and pull-requests/issues write
#   REPO             - "owner/repo"
#   PR_NUMBER        - pull request number to comment on
#   RUN_ID           - workflow run id to analyze
#   FAILURE_METADATA - sanitized JSON array of failed jobs (may be empty)

set -euo pipefail

: "${GH_TOKEN:?GH_TOKEN is required}"
: "${REPO:?REPO is required}"
: "${PR_NUMBER:?PR_NUMBER is required}"
: "${RUN_ID:?RUN_ID is required}"
FAILURE_METADATA="${FAILURE_METADATA:-[]}"

MAX_JOBS=20
MAX_LINES=10
MAX_LINE_CHARS=300
LOG_BYTE_CAP=3000000

strip_ansi() {
  sed 's/\x1b\[[0-9;]*[a-zA-Z]//g'
}

clip() {
  cut -c "1-${MAX_LINE_CHARS}"
}

indent4() {
  sed 's/^/    /'
}

BODY_FILE="$(mktemp)"
JOBS_TSV="$(mktemp)"
trap 'rm -f "$BODY_FILE" "$JOBS_TSV"' EXIT
RUN_URL="https://github.com/${REPO}/actions/runs/${RUN_ID}"

gh api "repos/${REPO}/actions/runs/${RUN_ID}/jobs" --paginate \
  --jq '[.jobs[] | select(.conclusion == "failure") | [.id, .name, .html_url] | @tsv] | .[]' \
  > "$JOBS_TSV" 2>/dev/null || true

{
  echo '## CI Failure Analysis'
  echo ''
  echo "> _Auto-generated by the CI Failure Comment workflow. This comment is updated in place each time CI fails on a new commit, so it always reflects the latest run — re-pushing or re-running CI will refresh the analysis below. Last updated $(date -u +'%Y-%m-%d %H:%M:%S UTC') from [workflow run ${RUN_ID}](${RUN_URL})._"
  echo ''
} > "$BODY_FILE"

JOB_COUNT=0
while IFS=$'\t' read -r JOB_ID JOB_NAME JOB_URL; do
  [ -n "${JOB_ID:-}" ] || continue
  if [ "$JOB_COUNT" -ge "$MAX_JOBS" ]; then
    echo "…and more failed jobs — see the [workflow run](${RUN_URL})." >> "$BODY_FILE"
    echo '' >> "$BODY_FILE"
    break
  fi
  JOB_COUNT=$((JOB_COUNT + 1))

  JOB_NAME_DISPLAY="$(printf '%s' "$JOB_NAME" | tr '\n' ' ' | clip)"
  FAILED_TESTS="$(printf '%s' "$FAILURE_METADATA" | jq -r --arg n "$JOB_NAME" \
    '[.[] | select(.job == $n) | .failed_tests // empty] | first // ""' 2>/dev/null || true)"

  LOG_TEXT="$(gh api "repos/${REPO}/actions/jobs/${JOB_ID}/logs" 2>/dev/null | head -c "$LOG_BYTE_CAP" | strip_ansi || true)"
  FAILED_LINES="$(printf '%s\n' "$LOG_TEXT" | grep -E '^\[  FAILED  \]' | sed 's/^\[  FAILED  \] //' | sed 's/ (.*//' | clip | head -n "$MAX_LINES" || true)"
  ERROR_LINES="$(printf '%s\n' "$LOG_TEXT" | grep -E ' (error|fatal error):' | clip | head -n "$MAX_LINES" || true)"

  {
    echo "### ❌ ${JOB_NAME_DISPLAY} — failure  [View logs](${JOB_URL})"
    echo ''
  } >> "$BODY_FILE"

  if [ -n "$FAILED_TESTS" ]; then
    {
      echo '**Failed tests:**'
      echo ''
      printf '%s\n' "$FAILED_TESTS" | indent4
      echo ''
    } >> "$BODY_FILE"
  fi

  if [ -n "$FAILED_LINES" ]; then
    {
      echo '**Failure output:**'
      echo ''
      printf '%s\n' "$FAILED_LINES" | indent4
      echo ''
    } >> "$BODY_FILE"
  elif [ -n "$ERROR_LINES" ]; then
    {
      echo '**Build errors:**'
      echo ''
      printf '%s\n' "$ERROR_LINES" | indent4
      echo ''
    } >> "$BODY_FILE"
  elif [ -z "$FAILED_TESTS" ]; then
    {
      echo 'No structured failure lines were found in the job log; see the linked job for details.'
      echo ''
    } >> "$BODY_FILE"
  fi
done < "$JOBS_TSV"

if [ "$JOB_COUNT" -eq 0 ]; then
  {
    echo "The workflow run failed but no failed jobs were reported by the API. See [workflow run ${RUN_ID}](${RUN_URL})."
    echo ''
  } >> "$BODY_FILE"
fi

COMMENT_ID="$(gh api "repos/${REPO}/issues/${PR_NUMBER}/comments" --paginate \
  --jq '[.[] | select(.body | contains("## CI Failure Analysis")) | .id] | first' 2>/dev/null || true)"

if [ -n "$COMMENT_ID" ] && [ "$COMMENT_ID" != "null" ]; then
  jq -Rs '{body: .}' "$BODY_FILE" \
    | gh api -X PATCH "repos/${REPO}/issues/comments/${COMMENT_ID}" --input - >/dev/null
else
  jq -Rs '{body: .}' "$BODY_FILE" \
    | gh api -X POST "repos/${REPO}/issues/${PR_NUMBER}/comments" --input - >/dev/null
fi
